import re

LABEL = re.compile(r'^\s*\*\s*Label:\s*(?P<label>.*?)\s*$')
ATTR = re.compile(r'([A-Z][A-Za-z ]*?):\s*(.*?)\s*,\s*(?=[A-Z][A-Za-z ]*?:\s|$)')
DECOR = re.compile(r'(%\s*$|%\s+softwareupdate|^\s*\$|Software Update Tool|Finding available software|Software Update found|No new software available)')

def parse(lines):
    recs = []
    used = []
    skip = []
    cur = None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = LABEL.match(ln)
        if m:
            cur = {'Label': m.group('label')}
            recs.append(cur)
            used.append(i)
            continue
        if cur is not None and ln[:1] in ('\t', ' ') and ':' in ln:
            s = ln.strip()
            if not s.endswith(','):
                s = s + ','
            found = False
            for k, v in ATTR.findall(s):
                cur[k.strip()] = v
                found = True
            if found:
                used.append(i)
                continue
        if DECOR.search(ln):
            skip.append(i)
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = [dict((k, r.get(k, '')) for k in keys) for r in recs]
    blocks = []
    if rows:
        blocks.append({'name': 'updates', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
